sys_ws_operation.operation_script:
(function process(request, response) {
    try {
        var reportId = request.pathParams.report_id;

        if (!reportId) {
            response.setStatus(400);
            response.setBody({ error: 'Missing report_id path parameter' });
            return;
        }

        var gr = new GlideRecord('x_293053_ai_inci_0_inv_report');
        if (!gr.get(reportId)) {
            response.setStatus(404);
            response.setBody({ error: 'Investigation report not found: ' + reportId });
            return;
        }

        var report = {
            sys_id: gr.getUniqueValue(),
            number: gr.getValue('number') || '',
            incident: gr.getValue('incident') || '',
            incident_display: gr.getDisplayValue('incident') || '',
            status: gr.getValue('status') || '',
            summary: gr.getValue('summary') || '',
            similar_incidents: gr.getValue('similar_incidents') || '',
            knowledge_results: gr.getValue('knowledge_results') || '',
            confidence_score: gr.getValue('confidence_score') || '0',
            suggested_next_steps: gr.getValue('suggested_next_steps') || '',
            sys_created_on: gr.getValue('sys_created_on') || '',
            sys_updated_on: gr.getValue('sys_updated_on') || '',
        };

        response.setStatus(200);
        response.setBody({ result: report });
    } catch (e) {
        gs.error('AI Investigation API: Error in getReport - ' + e);
        response.setStatus(500);
        response.setBody({ error: 'Internal server error: ' + e });
    }
})(request, response);
